values = {'a':1,'b':3,'c':3,'d':2,'e':1,'f':4,'g':2,'h':4,'i':1,'j':8,
          'k':5,'l':1,'m':3,'n':1,'o':1,'p':3,'q':10,'r':1,'s':1,'t':1,
          'u':1,'v':4,'w':4,'x':8,'y':4,'z':10}

def word_value(word):
    return sum(values[c] for c in word)

def matches(scrambled, word):
    return sorted(scrambled) == sorted(word)

mode = input().strip()
n = int(input())
players = []
for _ in range(n):
    name, hand = input().split()
    players.append((name, hand))
d = int(input())
dictionary = [input().strip() for _ in range(d)]

player_results = []
for name, hand in players:
    matched_words = [w for w in dictionary if matches(hand, w)]
    if not matched_words:
        continue

    if mode == "high":
        best_score = max(word_value(w) for w in matched_words)
    else:
        best_score = min(word_value(w) for w in matched_words)

    best_word = sorted(w for w in matched_words if word_value(w) == best_score)[0]
    player_results.append((name, best_word, best_score))

target = max(r[2] for r in player_results) if mode == "high" else min(r[2] for r in player_results)

for name, word, score in player_results:
    if score == target:
        print(name, word)
